import{_ as t,o,c as r,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse(`{"title":"Room Features · Beginner's Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/rooms.md","filePath":"en/features/rooms.md","lastUpdated":1786689844000}`),n={name:"en/features/rooms.md"};function s(i,e,h,d,l,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="room-features-·-beginner-s-guide" tabindex="-1">Room Features · Beginner&#39;s Guide <a class="header-anchor" href="#room-features-·-beginner-s-guide" aria-label="Permalink to &quot;Room Features · Beginner&#39;s Guide&quot;">​</a></h1><blockquote><p>Watch videos and share screens with friends, starting from this page.</p></blockquote><hr><h2 id="_1-feature-overview" tabindex="-1">1. Feature Overview <a class="header-anchor" href="#_1-feature-overview" aria-label="Permalink to &quot;1. Feature Overview&quot;">​</a></h2><p><strong>Room</strong> is the core of ZViewer&#39;s multi-user interaction. You can create a room, invite friends to join, and watch videos synchronously, share screens, or chat via voice in real time.</p><p>Core capabilities:</p><ul><li><strong>Synchronized Watching</strong>: When the host plays, pauses, or seeks, everyone&#39;s画面 stays in sync.</li><li><strong>Screen Sharing</strong>: The sharer streams their screen or application window in real time.</li><li><strong>Audience Management</strong>: The host can kick, mute, approve join requests, and transfer host privileges.</li><li><strong>Danmaku and Comments</strong>: Chat while watching, with support for Bilibili-style danmaku and pen annotations.</li><li><strong>Disconnect Protection</strong>: If the host briefly disconnects, the room does not close immediately and viewers continue watching.</li></ul><hr><h2 id="_2-room-mode-comparison" tabindex="-1">2. Room Mode Comparison <a class="header-anchor" href="#_2-room-mode-comparison" aria-label="Permalink to &quot;2. Room Mode Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Watch Together</th><th>Screen Share</th></tr></thead><tbody><tr><td><strong>What it does</strong></td><td>Everyone watches the same video link synchronously</td><td>The sharer broadcasts their screen/window in real time</td></tr><tr><td><strong>Best for</strong></td><td>Watching series and movies together</td><td>Demonstrations, remote collaboration, game streaming</td></tr><tr><td><strong>Playback control</strong></td><td>Host has full control; viewers can request control</td><td>The sharer controls their own stream</td></tr><tr><td><strong>Video source</strong></td><td>Paste an online video link or add from the room list</td><td>Local screen/window capture by the sharer</td></tr><tr><td><strong>Network requirements</strong></td><td>mp4 mode carries minimal sync data traffic; dash mode relays through the server, requiring higher server bandwidth</td><td>Higher</td></tr><tr><td><strong>Latency</strong></td><td>Low (sync playback, transmission delay)</td><td>Medium (WebRTC real-time transmission)</td></tr><tr><td><strong>Viewer count</strong></td><td>Almost unlimited</td><td>Limited by the sharer&#39;s upstream bandwidth</td></tr></tbody></table><blockquote><p>There is also an <strong>OBS stream-push mode</strong> for professional live streaming scenarios. See <a href="/en/features/screenshare">Screen Sharing and Streaming</a>.</p></blockquote><hr><h2 id="_3-creating-a-room" tabindex="-1">3. Creating a Room <a class="header-anchor" href="#_3-creating-a-room" aria-label="Permalink to &quot;3. Creating a Room&quot;">​</a></h2><p>Creating a room takes just three steps:</p><ol><li><strong>Open the homepage</strong> and click the <strong>&quot;Start Sharing&quot;</strong> button in the center of the page, or the <strong>&quot;Create Room&quot;</strong> button in the top-right corner.</li><li><strong>Select a mode</strong>: In the popup, choose <strong>&quot;Watch Together&quot;</strong> or <strong>&quot;Screen Share&quot;</strong>.</li><li><strong>Enter the room automatically</strong>: The system instantly creates the room, and you become the <strong>Host</strong> and enter the room interface.</li></ol><blockquote><p><strong>Tip</strong>: You do not need to register an account to create a room. The first time you use it, the system will prompt you to set a <strong>nickname</strong> so your friends can recognize you.</p></blockquote><hr><h2 id="_4-room-interface-overview" tabindex="-1">4. Room Interface Overview <a class="header-anchor" href="#_4-room-interface-overview" aria-label="Permalink to &quot;4. Room Interface Overview&quot;">​</a></h2><p>Once inside the room, you will see four main areas:</p><h3 id="top-bar" tabindex="-1">Top Bar <a class="header-anchor" href="#top-bar" aria-label="Permalink to &quot;Top Bar&quot;">​</a></h3><ul><li><strong>Room Name</strong>: Displays the current room name. Click to edit.</li><li><strong>Room ID</strong>: A numeric ID that you can share with friends for them to join.</li><li><strong>Online Count</strong>: Shows the current number of online viewers.</li><li><strong>&quot;Invite&quot; Button</strong>: Click to show sharing options.</li><li><strong>&quot;Settings&quot; Button</strong>: A gear icon that opens the room settings panel.</li><li><strong>&quot;Leave Room&quot; Button</strong>: Exit and close the room (only the host can close it).</li></ul><h3 id="player-area-watch-together-mode" tabindex="-1">Player Area (Watch Together Mode) <a class="header-anchor" href="#player-area-watch-together-mode" aria-label="Permalink to &quot;Player Area (Watch Together Mode)&quot;">​</a></h3><p>The central main area is the video player, supporting:</p><ul><li><strong>Play/Pause</strong>: Click the video or press the spacebar.</li><li><strong>Progress Bar</strong>: Drag to seek.</li><li><strong>Volume Control</strong>: Hover to adjust.</li><li><strong>Playback Speed</strong>: Supports 0.5x to 2x speed.</li><li><strong>Fullscreen</strong>: Click the fullscreen icon in the bottom-right corner.</li></ul><blockquote><p>In Screen Share mode, the central area displays the sharer&#39;s real-time stream.</p></blockquote><h3 id="bottom-three-cards" tabindex="-1">Bottom Three Cards <a class="header-anchor" href="#bottom-three-cards" aria-label="Permalink to &quot;Bottom Three Cards&quot;">​</a></h3><p>Below the player, there are three cards that expand when clicked:</p><table tabindex="0"><thead><tr><th>Card</th><th>Content</th></tr></thead><tbody><tr><td><strong>Video List</strong></td><td>All videos added to the current room; can switch, reorder, and add new ones</td></tr><tr><td><strong>Chat</strong></td><td>Real-time comments — supports text messages, danmaku mode, and pen annotations</td></tr><tr><td><strong>Viewer List</strong></td><td>Online viewers, showing nicknames and roles (host/viewer)</td></tr></tbody></table><h3 id="right-panel-room-info" tabindex="-1">Right Panel (Room Info) <a class="header-anchor" href="#right-panel-room-info" aria-label="Permalink to &quot;Right Panel (Room Info)&quot;">​</a></h3><p>Click the <strong>&quot;&gt;&quot;</strong> arrow on the right edge to expand the room info panel, which contains three tabs.</p><hr><h2 id="_5-room-info-panel-three-tabs" tabindex="-1">5. Room Info Panel (Three Tabs) <a class="header-anchor" href="#_5-room-info-panel-three-tabs" aria-label="Permalink to &quot;5. Room Info Panel (Three Tabs)&quot;">​</a></h2><h3 id="info-tab" tabindex="-1">Info Tab <a class="header-anchor" href="#info-tab" aria-label="Permalink to &quot;Info Tab&quot;">​</a></h3><ul><li><strong>Room ID</strong>: Copy and send to friends. They can enter it on the homepage to join.</li><li><strong>Share Link</strong>: Copy the link directly and send it to friends. They can click it to join.</li><li><strong>Room Name</strong>: The host can change the room&#39;s display name.</li><li><strong>Current Mode</strong>: Shows &quot;Watch Together&quot; or &quot;Screen Share&quot;.</li></ul><h3 id="permissions-tab" tabindex="-1">Permissions Tab <a class="header-anchor" href="#permissions-tab" aria-label="Permalink to &quot;Permissions Tab&quot;">​</a></h3><p>The host can configure room access control:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Room Password</strong></td><td>When enabled, joiners must enter a password to enter</td></tr><tr><td><strong>Max Members</strong></td><td>Limits the maximum number of viewers in the room (including the host)</td></tr><tr><td><strong>Join Approval</strong></td><td>When enabled, new viewers require the host to click &quot;Approve&quot; or &quot;Deny&quot; in a notification</td></tr><tr><td><strong>Auto Approve</strong></td><td>When approval is enabled, whitelisted or followed users are automatically approved without manual confirmation</td></tr></tbody></table><hr><h2 id="_6-three-ways-to-invite-friends" tabindex="-1">6. Three Ways to Invite Friends <a class="header-anchor" href="#_6-three-ways-to-invite-friends" aria-label="Permalink to &quot;6. Three Ways to Invite Friends&quot;">​</a></h2><h3 id="method-1-room-id" tabindex="-1">Method 1: Room ID <a class="header-anchor" href="#method-1-room-id" aria-label="Permalink to &quot;Method 1: Room ID&quot;">​</a></h3><p>Copy the <strong>Room ID</strong> from the room info panel and send it to your friends. On the homepage, they click <strong>&quot;Join Room&quot;</strong> and enter the Room ID.</p><h3 id="method-2-share-link" tabindex="-1">Method 2: Share Link <a class="header-anchor" href="#method-2-share-link" aria-label="Permalink to &quot;Method 2: Share Link&quot;">​</a></h3><p>Click the <strong>&quot;Invite&quot;</strong> button on the top bar, select <strong>&quot;Copy Link&quot;</strong>, and send the link to your friends. They click the link to enter the room directly (if a password is set, they will be prompted to enter it).</p><h3 id="method-3-room-list" tabindex="-1">Method 3: Room List <a class="header-anchor" href="#method-3-room-list" aria-label="Permalink to &quot;Method 3: Room List&quot;">​</a></h3><p>Friends can browse the <strong>&quot;Public Rooms&quot;</strong> list on the homepage, find your room, and click the <strong>&quot;Join&quot;</strong> button. The host can set the room to &quot;Public&quot; or &quot;Unlisted&quot; in the permissions settings.</p><hr><h2 id="_7-joining-a-room-—-scenarios" tabindex="-1">7. Joining a Room — Scenarios <a class="header-anchor" href="#_7-joining-a-room-—-scenarios" aria-label="Permalink to &quot;7. Joining a Room — Scenarios&quot;">​</a></h2><p>Depending on the host&#39;s settings, joining a room works differently:</p><h3 id="no-password-no-approval" tabindex="-1">No Password + No Approval <a class="header-anchor" href="#no-password-no-approval" aria-label="Permalink to &quot;No Password + No Approval&quot;">​</a></h3><p>Click the link or enter the Room ID to <strong>enter the room directly</strong> and start watching.</p><h3 id="password-protected" tabindex="-1">Password Protected <a class="header-anchor" href="#password-protected" aria-label="Permalink to &quot;Password Protected&quot;">​</a></h3><p>A <strong>password input</strong> dialog appears before entering. Enter the correct password to proceed. The password is set by the host in the Permissions tab.</p><h3 id="requires-approval" tabindex="-1">Requires Approval <a class="header-anchor" href="#requires-approval" aria-label="Permalink to &quot;Requires Approval&quot;">​</a></h3><p>The host has enabled &quot;Join Approval&quot;. When you click join, the page shows <strong>&quot;Waiting for host approval&quot;</strong>. The host receives a notification and clicks &quot;Approve&quot; for you to enter.</p><h3 id="room-full" tabindex="-1">Room Full <a class="header-anchor" href="#room-full" aria-label="Permalink to &quot;Room Full&quot;">​</a></h3><p>If the room has reached the &quot;Max Members&quot; limit, you will see a <strong>&quot;Room is full&quot;</strong> message and cannot join.</p><hr><h2 id="_8-host-disconnect-protection" tabindex="-1">8. Host Disconnect Protection <a class="header-anchor" href="#_8-host-disconnect-protection" aria-label="Permalink to &quot;8. Host Disconnect Protection&quot;">​</a></h2><p>ZViewer has a robust disconnect protection mechanism to prevent the room from crashing if the host temporarily disconnects:</p><table tabindex="0"><thead><tr><th>Phase</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Disconnected (0-10 seconds)</strong></td><td>The server takes over playback state and continues broadcasting the current progress to viewers. Viewers experience <strong>no interruption</strong></td></tr><tr><td><strong>Disconnected (10 seconds - 10 minutes)</strong></td><td>Viewers can freely control playback (pause/seek). The room runs normally</td></tr><tr><td><strong>Timeout close (after 10 minutes)</strong></td><td>If the host has not reconnected, the room automatically closes and all viewers are removed</td></tr><tr><td><strong>Host reconnects</strong></td><td>If the host reconnects within 10 minutes, control is automatically restored and playback state syncs to the latest position</td></tr></tbody></table><blockquote><p><strong>Tip</strong>: If it is just a network fluctuation, there is no need to worry — the room will wait for you.</p></blockquote><hr><h2 id="_9-frequently-asked-questions" tabindex="-1">9. Frequently Asked Questions <a class="header-anchor" href="#_9-frequently-asked-questions" aria-label="Permalink to &quot;9. Frequently Asked Questions&quot;">​</a></h2><h3 id="q-what-is-the-maximum-number-of-people-who-can-watch-together" tabindex="-1">Q: What is the maximum number of people who can watch together? <a class="header-anchor" href="#q-what-is-the-maximum-number-of-people-who-can-watch-together" aria-label="Permalink to &quot;Q: What is the maximum number of people who can watch together?&quot;">​</a></h3><p>A: There is no hard limit, but it is recommended to keep it under 10 people for the best experience, depending on the host&#39;s network bandwidth and server load.</p><h3 id="q-do-i-need-to-register-an-account-to-join-a-room" tabindex="-1">Q: Do I need to register an account to join a room? <a class="header-anchor" href="#q-do-i-need-to-register-an-account-to-join-a-room" aria-label="Permalink to &quot;Q: Do I need to register an account to join a room?&quot;">​</a></h3><p>A: No. However, registering allows you to keep your avatar and nickname settings.</p><h3 id="q-why-can-t-i-see-the-video" tabindex="-1">Q: Why can&#39;t I see the video? <a class="header-anchor" href="#q-why-can-t-i-see-the-video" aria-label="Permalink to &quot;Q: Why can&#39;t I see the video?&quot;">​</a></h3><p>A: Check the following:</p><ul><li>Is the video link valid (publicly accessible)?</li><li>Is it being blocked by a browser ad blocker (try disabling the extension or using incognito mode)?</li><li>Are you in approval-pending state and have not yet been approved by the host?</li></ul><h3 id="q-in-screen-share-mode-can-the-other-person-see-my-entire-screen" tabindex="-1">Q: In Screen Share mode, can the other person see my entire screen? <a class="header-anchor" href="#q-in-screen-share-mode-can-the-other-person-see-my-entire-screen" aria-label="Permalink to &quot;Q: In Screen Share mode, can the other person see my entire screen?&quot;">​</a></h3><p>A: You can choose to share your <strong>entire screen</strong>, a <strong>specific application window</strong>, or a <strong>browser tab</strong>. It is recommended to share only the window you need to protect your privacy.</p><h3 id="q-what-happens-when-the-host-leaves" tabindex="-1">Q: What happens when the host leaves? <a class="header-anchor" href="#q-what-happens-when-the-host-leaves" aria-label="Permalink to &quot;Q: What happens when the host leaves?&quot;">​</a></h3><p>A: When the host leaves, the room automatically closes and all viewers are removed. If it is just a disconnect, there is a 10-minute protection window (see Section 8).</p><h3 id="q-how-do-i-change-the-room-password" tabindex="-1">Q: How do I change the room password? <a class="header-anchor" href="#q-how-do-i-change-the-room-password" aria-label="Permalink to &quot;Q: How do I change the room password?&quot;">​</a></h3><p>A: The host goes to the <strong>&quot;Permissions&quot; tab</strong> in the right panel, finds the &quot;Room Password&quot; setting, clicks <strong>&quot;Change&quot;</strong> and enters the new password.</p><h3 id="q-can-i-join-a-room-from-a-mobile-device" tabindex="-1">Q: Can I join a room from a mobile device? <a class="header-anchor" href="#q-can-i-join-a-room-from-a-mobile-device" aria-label="Permalink to &quot;Q: Can I join a room from a mobile device?&quot;">​</a></h3><p>A: Yes. ZViewer is a web application. Open the link in your mobile browser to join, supporting basic playback sync and chat functions.</p><hr><blockquote><p>More questions? See the <a href="/en/guide/faq">FAQ</a> or contact the administrator.</p></blockquote>',80)])])}const p=t(n,[["render",s]]);export{u as __pageData,p as default};
